#!/usr/bin/env python3
"""Reversible, exact-source vLLM 0.29.0 preview extension. Default is check only.

Expected baseline already includes Spark Lab request controls and native metrics.
Deploy only while the owned inference server is stopped. No GPU calls here.
"""
from __future__ import annotations
import argparse, ast, base64, difflib, hashlib, importlib.metadata, importlib.util
import json, os, tempfile, zlib
from pathlib import Path

PAYLOAD = {'sampling_params.py': {'before_sha256': '7428ee8743af1fe3ec8ccd285b3ad79913bd906227d98f2a59401f3db56626de', 'after_sha256': 'dc12626e594d564b74977ff1341bd2c586eaa48d90f43b31fef40c67fc317849', 'before': '', 'after': ''}, 'v1/worker/gpu/sample/output.py': {'before_sha256': '1a1abac89cc6cc2278b6f984e4e20dbf82df81130112a875eeb9d72a694f8230', 'after_sha256': '8cdd2591e1c9dd6ec71636f6d3ee39f8f0b311235084cf48c32b9d83d1889513', 'before': '', 'after': ''}, 'model_executor/models/diffusion_gemma.py': {'before_sha256': '1e8cee4e58234ef8efa42e954eb24b88c1264cc3ffeec05546254040375bd1ed', 'after_sha256': 'b379ce87b919491e4a0c4d92df19bcf9dc2f4c49558529dc7da694fa2a06452e', 'before': '', 'after': ''}, 'v1/outputs.py': {'before_sha256': '9e3be802fd0107ace7f77806357e3fcd58670c1f705c8395053c751b2ad35841', 'after_sha256': '34019ba418b7d2ea42b82e85d4357451708d1f72fe505252d18b26b1f127adef', 'before': '', 'after': ''}, 'v1/worker/gpu/async_utils.py': {'before_sha256': '36bd876f1c2cf648ed9436c66205db39df7bd4f9b0da90f507fed8b3159840c5', 'after_sha256': '29f7115fb947c61cc74aa9fc3f34e4631b33c35aa12be957a4879ac7c39bbd52', 'before': '', 'after': ''}, 'v1/engine/__init__.py': {'before_sha256': '4e59828787634123026a6b424f48c21d691913dd338b59dd13f25fa260f2284b', 'after_sha256': '4164dad491915dd5fc59f7a955fc82fb9c6756f18c3c5ed070b10baec61542ca', 'before': '', 'after': ''}, 'v1/core/sched/scheduler.py': {'before_sha256': 'e177979bc578a5b531e460fba97da4f50d37501b700cd93fbd1d414ae5923fa8', 'after_sha256': 'd6ffc4de0581f75f3ba1acc5b26b81bc48828be52ab816b3b5f6f6d3f5b15c49', 'before': '', 'after': ''}, 'outputs.py': {'before_sha256': '137b1997d386d319dff8394312b0d37ad86254d53c59d9ce42122f7cab697ab5', 'after_sha256': '405f0ac42c3cb9327dd8ad216b367821d697f04af7f7f57d3ef0e9526e3cd543', 'before': '', 'after': ''}, 'v1/engine/output_processor.py': {'before_sha256': '223a1e1b2078404cd6ea7f8625c2391dfdbdbe65b46f1c3f0cc71b3ea991d432', 'after_sha256': '9a72f836a34fbe997382addd5192c8c4abf3b8ba3f48b03cc070ef4565a0da22', 'before': '', 'after': ''}, 'entrypoints/openai/chat_completion/serving.py': {'before_sha256': '09c89b93fce527e5c0bf2a413c217bb720a7cf2417263b24afe9dc38ae068b01', 'after_sha256': '810159d5e05f53f5d10e7d9c0321bc3af6ab315d0bb28d05b07a68c093616ef1', 'before': '', 'after': ''}, 'spark_lab_diffusion_preview.py': {'before_sha256': None, 'after_sha256': 'c9bbfbb5235834c103fea471648e13eb62ca1abc9511b9dad42de3de30a08d12', 'before': None, 'after': ''}}

def unpack(value):
    return zlib.decompress(base64.b64decode(value)) if value is not None else None

def digest(data):
    return hashlib.sha256(data).hexdigest() if data is not None else None

def atomic_write(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    fd, tmp = tempfile.mkstemp(prefix=path.name+'.', dir=path.parent)
    try:
        with os.fdopen(fd, 'wb') as f:
            f.write(data)
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)

def apply(root, mode, output_dir):
    changes = []
    states = []
    for name, entry in PAYLOAD.items():
        path = root/name
        current = path.read_bytes() if path.exists() else None
        got = digest(current)
        if got not in (entry['before_sha256'], entry['after_sha256']):
            raise RuntimeError(f'Refusing unknown source {name}: {got}')
        state = 'patched' if got == entry['after_sha256'] else 'original'
        states.append({'path':name,'state':state,'sha256':got})
        target = unpack(entry['before'] if mode == 'revert' else entry['after'])
        if target is not None: ast.parse(target, filename=name)
        if current != target: changes.append((path,current,target))
    # Validate every file before performing any write.
    output_dir.mkdir(parents=True, exist_ok=True)
    diff = []
    for name, entry in PAYLOAD.items():
        before = (unpack(entry['before']) or b'').decode().splitlines(keepends=True)
        after = unpack(entry['after']).decode().splitlines(keepends=True)
        diff.extend(difflib.unified_diff(before, after, 'a/'+name, 'b/'+name))
    (output_dir/'preview.patch').write_text(''.join(diff))
    manifest={'version':'spark-lab-diffusion-preview-v1','vllm_version':'0.29.0',
              'mode':mode,'root':str(root),'files':states,
              'hashes':{p:{k:v for k,v in e.items() if k.endswith('sha256')}
                        for p,e in PAYLOAD.items()}}
    (output_dir/'preview-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    if mode != 'check':
        applied=[]
        try:
            for path,current,target in changes:
                if target is None: path.unlink()
                else: atomic_write(path,target)
                applied.append((path,current))
        except BaseException:
            for path,current in reversed(applied):
                if current is None: path.unlink(missing_ok=True)
                else: atomic_write(path,current)
            raise
    return {'mode':mode,'changed_files':len(changes) if mode!='check' else 0,
            'pending_files':len(changes),'source_states':states}

def main():
    ap=argparse.ArgumentParser(description=__doc__)
    mode=ap.add_mutually_exclusive_group()
    mode.add_argument('--apply',action='store_true')
    mode.add_argument('--revert',action='store_true')
    ap.add_argument('--vllm-root',type=Path)
    ap.add_argument('--output-dir',type=Path,required=True)
    args=ap.parse_args()
    if args.vllm_root is None:
        version=importlib.metadata.version('vllm')
        if version!='0.29.0': raise SystemExit(f'Expected vLLM 0.29.0, got {version}')
        spec=importlib.util.find_spec('vllm')
        args.vllm_root=Path(spec.origin).parent
    else:
        # CPU fixture mode still enforces exact hashes of all baseline sources.
        args.vllm_root=args.vllm_root.resolve()
    print(json.dumps(apply(args.vllm_root,
          'apply' if args.apply else 'revert' if args.revert else 'check',
          args.output_dir),indent=2))

if __name__=='__main__': main()
